#!/usr/bin/env python
"""Release helper scripts for Flask-RESTful."""

import argparse
import sys


def point_release(version):
    # type: (str) -> str
    """Bump the patch component of a semantic version.

    >>> point_release('1.2.3')
    '1.2.4'
    >>> point_release('2.0.9')
    '2.0.10'
    """
    parts = version.split('.')
    if len(parts) < 3:
        raise ValueError(
            'Expected a semantic version like "1.2.3", got {!r}'.format(version)
        )
    try:
        parts[2] = str(int(parts[2]) + 1)
    except ValueError:
        raise ValueError(
            'Patch component must be an integer, got {!r}'.format(version)
        )
    return '.'.join(parts)


def main(argv=None):
    parser = argparse.ArgumentParser(
        description='Bump version numbers for a release.'
    )
    parser.add_argument(
        'version',
        help='current semantic version, e.g. 1.2.3',
    )
    args = parser.parse_args(argv)
    try:
        print(point_release(args.version))
    except ValueError as exc:
        parser.error(str(exc))
    return 0


if __name__ == '__main__':
    sys.exit(main())

